package com.coffee.management.organization.interfaces.rest;
import com.coffee.management.organization.application.OrganizationException;import java.time.Instant;import java.util.Map;import org.springframework.http.*;import org.springframework.web.bind.MethodArgumentNotValidException;import org.springframework.web.bind.annotation.*;
@RestControllerAdvice public class ApiExceptionHandler {@ExceptionHandler(OrganizationException.class)ResponseEntity<?> organization(OrganizationException e){return ResponseEntity.status(e.status()).body(Map.of("code",e.code(),"message",e.getMessage(),"timestamp",Instant.now()));}@ExceptionHandler({IllegalArgumentException.class,MethodArgumentNotValidException.class})ResponseEntity<?> validation(Exception e){return ResponseEntity.unprocessableEntity().body(Map.of("code","VALIDATION_FAILED","message","Request validation failed","timestamp",Instant.now()));}}
